<?php
namespace Tests\Feature\Api;
use App\Models\HealthFacility; use App\Models\Organization; use App\Models\Permission; use App\Models\Role; use App\Models\Site; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class InventoryModuleCompletionTest extends TestCase {
 use RefreshDatabase;
 public function test_web_inventory_workspace_replaces_placeholder_and_creates_record():void{$o=Organization::create(['code'=>'WEB-INV','name'=>'Organisation Web']);$f=HealthFacility::create(['organization_id'=>$o->id,'code'=>'F','name'=>'Centre','facility_type'=>'clinic']);$s=Site::create(['organization_id'=>$o->id,'health_facility_id'=>$f->id,'code'=>'S','name'=>'Pharmacie Web','site_type'=>'stock']);$permissions=collect(['inventories.view','inventories.manage','inventories.validate'])->map(fn($c)=>Permission::firstOrCreate(['code'=>$c],['name'=>$c]));$role=Role::create(['code'=>'web_inventory','name'=>'Inventaire Web']);$role->permissions()->attach($permissions);$u=User::factory()->create(['organization_id'=>$o->id]);$u->roles()->attach($role,['scope_type'=>'organization','scope_id'=>$o->id]);$this->actingAs($u)->get('/inventories')->assertOk()->assertSee('Inventaires physiques')->assertSee('inventory-create')->assertSee('Pharmacie Web');$this->actingAs($u)->post("/organizations/{$o->id}/inventories",['site_id'=>$s->id,'reference'=>'WEB-001','inventory_type'=>'monthly','period_date'=>today()->toDateString()])->assertRedirect()->assertSessionHas('status');$this->assertDatabaseHas('inventories',['reference'=>'WEB-001','status'=>'draft']);}
 public function test_mobile_inventory_route_and_offline_outbox_are_real():void{$router=file_get_contents(base_path('../mobile/lib/src/core/routing/app_router.dart'));$service=file_get_contents(base_path('../mobile/lib/src/features/inventories/data/inventory_service.dart'));$page=file_get_contents(base_path('../mobile/lib/src/features/inventories/presentation/inventories_page.dart'));$this->assertStringContainsString('const InventoriesPage()', $router);$this->assertStringNotContainsString("('/inventories', 'Inventaires'",$router);$this->assertStringContainsString('_operations.execute(',$service);$this->assertStringContainsString("entityType: 'inventories'",$service);$this->assertStringContainsString('LocalFirstRepository',$service);$this->assertStringContainsString("'offline_uuid'",$service);$this->assertStringContainsString('Mode hors connexion',$page);}
}
